insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k1','k',1,NULL,'Türen','Türen gehören zu den am dichtesten geregelten und zugleich am stärksten wahrgenommenen Bauteilen: Sie werden täglich berührt, tragen Anforderungen von Schall über Brand bis Einbruch und prägen jeden Raumübergang. Dieses Themenfeld gliedert sich nach Einsatzort und Funktion.',NULL,NULL,ARRAY['e1','x3haustuer','kt1']::text[],'[]'::jsonb,NULL,1),
('k2i','k',2,'k1','Innentüren','Innentüren sind das Mengenbauteil des Innenausbaus. Ihre Qualität entscheidet sich an vier Stellen: Türblatt, Zarge, Beschlag und Öffnungsart. Wer hier Standards klug wählt, spart Kosten ohne sichtbaren Verlust; wer gestalten will, findet an jeder der vier Stellen Hebel.','Planungsrelevant ist vor allem das Zusammenspiel: Ein hochwertiges Türblatt in einer schlichten CPL-Zarge wirkt inkonsistent, ein flächenbündiges Konzept scheitert oft nicht am Budget, sondern an der zu spät bedachten Wandtoleranz. Empfehlung: Türliste früh anlegen und je Türtyp Blatt, Zarge, Beschlag und Anforderungen (Schall, Feuchtraum) gemeinsam festlegen.',NULL,'{}'::text[],'[{"t":"DIN 18101 Türen: Türblattgrößen, Bandsitz","stand":"2014-08","u":"https://www.dinmedia.de/de/norm/din-18101/204907014","geprueft":"2026-08-16"},{"t":"Baunetzwissen Fenster und Türen (weiterführend)","u":"https://www.baunetzwissen.de/fenster-und-tueren","geprueft":"2026-08-16"}]'::jsonb,NULL,2),
('k3blatt','k',3,'k2i','Türblatt','Das Türblatt bestimmt Haptik, Schallschutz und Optik der Tür. Die drei Entscheidungen: innerer Aufbau (Einlage), Oberfläche und Kantenausbildung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,3),
('k4aufbau','k',4,'k3blatt','Aufbau: Wabe, Röhrenspan, Vollspan','Die Einlage im Türblatt reicht von der leichten Wabe (hohl klingend, günstig) über Röhrenspan bis zur Vollspanplatte (schwer, schalldämmend, wertige Haptik). Man hört und fühlt den Unterschied bei jedem Schließen.','Faustregel für Wohnbau: Röhrenspan als Minimum, Vollspan wo Wertigkeit oder Schallschutz zählt. Wabe nur bei hartem Budget und untergeordneten Räumen. Der Aufpreis Röhrenspan zu Vollspan ist klein im Verhältnis zum spürbaren Unterschied; hier zu sparen ist die falsch verstandene Kostenstelle.',NULL,'{}'::text[],'[]'::jsonb,NULL,4),
('k4oberfl','k',4,'k3blatt','Oberflächen: CPL, HPL, Furnier, Lack','CPL ist der robuste Standard, HPL die härtere Variante für starke Beanspruchung, Furnier bringt echtes Holz, Lack die homogene, aber empfindlichste Fläche. Die Wahl ist eine Abwägung aus Beanspruchung, Budget und gestalterischem Anspruch.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,5),
('k4falz','k',4,'k3blatt','Gefälzt oder stumpf einschlagend','Das gefälzte Türblatt überdeckt die Zarge (gutmütig, Standard), das stumpfe schließt flächig in ihr (präziser, toleranzempfindlicher). Diese kleine Entscheidung prägt die gesamte Anmutung der Tür.',NULL,NULL,ARRAY['e3unsichtbar']::text[],'[]'::jsonb,NULL,6),
('k3zarge','k',3,'k2i','Zarge','Die Zarge verbindet Türblatt und Wand und rahmt die Öffnung. Ihre Bauform (Umfassungs-, Block-, Eckzarge oder verdecktes System) entscheidet über Erscheinung, Montageablauf und Toleranzverhalten.','Die Zargenwahl ist früher zu treffen, als viele denken: Verdeckte Systeme brauchen Entscheidungen vor dem Trockenbau, Umfassungszargen verzeihen fast alles bis zum Schluss. Wer im Bestand arbeitet, prüft zuerst Wanddicken-Streuung; sie bestimmt, ob Standardmaulweiten funktionieren.',NULL,ARRAY['e2artik']::text[],'[]'::jsonb,NULL,7),
('k4umf','k',4,'k3zarge','Umfassungszarge','Die Umfassungszarge umgreift die Wand beidseitig und ist der Standard im Innenausbau: schnell montiert, toleranzverzeihend, in jedem System verfügbar. Ihre sichtbaren Teile sind Zargenspiegel und Falzbekleidung.','Stärke der Umfassungszarge ist die Trennung von Rohbau und Ausbau: Sie wird nach Wandfertigstellung eingeschäumt und überdeckt beidseitig die Anschlussfuge. Grenze: Bei sehr dicken oder stark streuenden Bestandswänden werden Sondermaulweiten nötig; ab da lohnt der Vergleich mit der Blockzarge.',NULL,'{}'::text[],'[]'::jsonb,NULL,8),
('k5spiegel','k',5,'k4umf','Zargenspiegel','Der Zargenspiegel ist der sichtbare, flächige Teil der Umfassungszarge, der die Wandöffnung rahmt. Er bestimmt maßgeblich, wie schwer oder leicht eine Tür im Raum wirkt. Standardbreiten liegen bei etwa 60 bis 70 mm.','Die Spiegelbreite ist eine der wenigen Stellschrauben, mit denen sich Standard-Innentüren gestalterisch differenzieren lassen, ohne das System zu verlassen. Schmale Spiegel (ab ca. 45 mm) wirken präziser, verzeihen aber weniger Wandtoleranz, weil weniger Überdeckung bleibt. Typischer Planungsfehler: Spiegel und Sockelleiste kollidieren in Höhe und Vorsprung; das Aufeinandertreffen beider Profile früh zeichnen.','Übliche Spiegelbreiten 60/70 mm, Sonderbreiten 45 bis 100 mm je nach System. Überdeckung des Wandanschlusses min. 15 mm bei üblichen Trockenbautoleranzen (Ebenheit nach DIN 18202 Tab. 3 prüfen). Ausschreibung: Spiegelbreite, Kantenprofil, Falzbekleidung und Maulweitenbereich getrennt angeben; Maulweite als Toleranzbereich (z. B. 100 +15 mm), nie als Festmaß. Ab hier: Systemunterlagen des Herstellers.',ARRAY['e4spiegelgest']::text[],'[{"t":"DIN 18202 Toleranzen im Hochbau","stand":"2019-07","u":"https://www.dinmedia.de/de/norm/din-18202/307314612","geprueft":"2026-08-16"},{"t":"DIN 18101 Türen: Maßordnung","stand":"2014-08","u":"https://www.dinmedia.de/de/norm/din-18101/204907014","geprueft":"2026-08-16"}]'::jsonb,NULL,9),
('k6breite','k',6,'k5spiegel','Spiegelbreite und Proportion','Je schmaler der Spiegel, desto grafischer und leiser die Tür; je breiter, desto gerahmter und traditioneller. Die Breite sollte im Verhältnis zu Sockelleiste, Türhöhe und Wandabwicklung entschieden werden, nicht isoliert.','Praxisregel: Spiegelbreite und Sockelleistenhöhe aufeinander abstimmen und an einer Musterachse im Maßstab 1:1 prüfen. Bei raumhohen Türen kippt die Wirkung: Der Spiegel wird zur vertikalen Linie und verträgt Schmalheit besser als bei Normhöhen.',NULL,'{}'::text[],'[]'::jsonb,NULL,10),
('k6kante','k',6,'k5spiegel','Kantenausbildung','Gerundet (Standard bei CPL, gutmütig), scharfkantig (präzise, stoßempfindlicher) oder mit Schattennut zur Wand: Die Kante ist ein kleines Detail mit großer Nahwirkung.',NULL,'Rundungen üblich R 2 bis 3 mm. Scharfkantige Ausführung meist nur bei Lack oder Furnier sinnvoll (Kantenstoß bei CPL sichtbar). Schattennut zur Wand als umlaufende Fuge ca. 5 x 5 mm; erfordert erhöhte Putz-/Spachtelqualität (Q3 aufwärts) am Anschluss. Ab hier: Systemunterlagen und Bemusterung.','{}'::text[],'[]'::jsonb,NULL,11),
('k6mat','k',6,'k5spiegel','Materialität und Oberfläche','Zargenspiegel in Blattoberfläche (ruhig, Standard), in Kontrastton (rahmend) oder in Wandfarbe (verschwindet fast): Drei Strategien mit klar unterschiedlicher Raumwirkung.',NULL,NULL,ARRAY['e2artik']::text[],'[]'::jsonb,NULL,12),
('k5maul','k',5,'k4umf','Falzbekleidung und Maulweite','Die Maulweite ist der Wanddickenbereich, den die Zarge aufnehmen kann. Sie ist das kritische Bestellmaß: Falsch gemessen, passt die ganze Zarge nicht.','Wanddicke inklusive aller Beläge messen, nicht die Rohbauwand: Fliesenspiegel, Putzstärken und beidseitige Beplankungsaufbauten wandern in die Maulweite. Im Trockenbau die tatsächliche, nicht die geplante Beplankung prüfen. Bestandsbauten: mehrere Messpunkte je Öffnung, Streuung dokumentieren.',NULL,'{}'::text[],'[]'::jsonb,NULL,13),
('k5wand','k',5,'k4umf','Wandanschluss und Montage','Montiert wird heute fast immer mit Montageschaum und Distanzklötzen. Die Qualität entscheidet sich an der Lage im Anschlag und an der Fuge zur Wand.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,14),
('k6trocken','k',6,'k5wand','Anschluss an Trockenbau vs. Massivwand','Trockenbauwände brauchen ausgesteifte Türöffnungen (UA-Profile ab bestimmten Blattgewichten), Massivwände saubere Laibungen. Der Zargentyp bleibt oft gleich, die Vorleistung nicht.','Häufigste Mängelquelle: schwere Türblätter (Vollspan, Schallschutz, raumhoch) an Standard-CW-Ständern. Ab ca. 25 kg Blattgewicht UA-Verstärkung vorsehen und im Trockenbau-LV explizit ausschreiben; die Türenfirma setzt sie nicht, sie findet sie vor oder eben nicht.',NULL,'{}'::text[],'[{"t":"DIN 18183-1 Trennwände und Vorsatzschalen aus Gipsplatten","stand":"2018-05","u":"https://www.dinmedia.de/de/norm/din-18183-1/287703861","geprueft":"2026-08-16"}]'::jsonb,NULL,15);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k7fuge','k',7,'k6trocken','Detail: Schattenfuge Zarge/Wand, Toleranzen','Die letzte Ebene: Wie genau trifft der Zargenspiegel auf die Wandfläche? Pressfuge, Acrylfuge oder bewusste Schattenfuge sind die drei Antworten.',NULL,'Pressfuge nur bei Q3/Q4-Flächen realistisch. Acrylfuge ist wartungsanfällig und bei Sichtqualität zu vermeiden. Schattenfuge (ca. 5 mm, ggf. mit Fugenprofil) macht Toleranzen zum Gestaltungsmittel, verlangt aber parallele Kanten: Ebenheits- und Winkeltoleranzen nach DIN 18202 reichen dafür nicht automatisch; erhöhte Anforderung gesondert vereinbaren. Ab hier: Detailzeichnung 1:1 und Bemusterung am Objekt.','{}'::text[],'[{"t":"DIN 18202 Toleranzen im Hochbau","stand":"2019-07","u":"https://www.dinmedia.de/de/norm/din-18202/307314612","geprueft":"2026-08-16"}]'::jsonb,NULL,16),
('k4block','k',4,'k3zarge','Blockzarge','Die Blockzarge sitzt als kompakter Block in der Laibung, ohne die Wand zu umgreifen. Klassisch im Altbau und überall dort, wo Wanddicken stark streuen oder die Laibung sichtbar bleiben soll.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,17),
('k4eck','k',4,'k3zarge','Eckzarge','Die Eckzarge umgreift nur eine Wandecke, typisch im Objektbau (Stahlzargen) und bei gefliesten Wänden, wo eine zweite Bekleidungsseite entfallen kann.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,18),
('k4verdeckt','k',4,'k3zarge','Verdeckte Zarge, flächenbündige Systeme','Systeme mit eingeputzter Aluminiumzarge lassen Tür und Wand in eine Ebene fallen; die Tür wird zur Fläche in der Fläche. Der Preis: frühe Festlegung, präzise Vorleistungen, höhere Kosten.','Verdeckte Systeme müssen vor dem Verspachteln geplant und geliefert sein und binden früh an einen Hersteller. Anspruchsvoll sind die Übergänge: Sockelleiste (läuft sie durch?), Wandflächenqualität (Q4 sinnvoll) und die Bänderwahl (verdeckt liegend, 3D-verstellbar). Wirtschaftlich fair rechnet man das Gesamtpaket, nicht den Zargenpreis.',NULL,ARRAY['e3unsichtbar']::text[],'[]'::jsonb,NULL,19),
('k3besch','k',3,'k2i','Beschläge','Bänder, Drücker, Schlösser und Schließer: Beschläge sind die Mechanik der Tür und ihr wichtigster Berührungspunkt. Hier treffen Ergonomie, Haltbarkeit und Gestaltung aufeinander.',NULL,NULL,ARRAY['e2hand']::text[],'[]'::jsonb,NULL,20),
('k4band','k',4,'k3besch','Bänder: aufliegend, verdeckt, 3D-verstellbar','Sichtbare Bänder sind robust und justierbar, verdeckt liegende Bänder machen die Tür grafisch ruhig, kosten aber mehr und begrenzen teils den Öffnungswinkel. 3D-Verstellbarkeit ist bei schweren Blättern Pflicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,21),
('k4drueck','k',4,'k3besch','Drücker und Schlösser','Der Drücker wird tausendfach berührt: Form, Material und Rückstellfeder entscheiden über die gefühlte Qualität des ganzen Ausbaus. Schlösser reichen vom Buntbartschloss bis zum Objektstandard mit Wechselgarnitur.',NULL,NULL,ARRAY['e3druecker']::text[],'[]'::jsonb,NULL,22),
('k4schliess','k',4,'k3besch','Türschließer und Feststellanlagen','Obenliegend, integriert oder als Freilauftürschließer: Bei Funktionstüren oft Pflicht, gestalterisch fast immer ein Kompromiss, der früh mitgedacht werden sollte.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,23),
('k3oeff','k',3,'k2i','Öffnungsarten','Anschlag-, Schiebe-, Falt-, Pendel- oder Drehtür: Die Öffnungsart ist zuerst eine Grundriss-Entscheidung (Aufschlagfläche!) und erst danach eine Frage der Technik.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,24),
('k4anschlag','k',4,'k3oeff','Anschlagtür, DIN links/rechts','Der Normalfall. DIN-Richtung (links/rechts, definiert von der Bandseite aus gesehen) und Aufschlagrichtung gehören in jeden Grundriss; nachträgliche Änderungen ziehen Zarge, Blatt und Elektro nach sich.',NULL,NULL,'{}'::text[],'[{"t":"DIN 107 Bezeichnung links/rechts im Bauwesen","stand":"1974-04","u":"https://www.dinmedia.de/de/norm/din-107/702361","geprueft":"2026-08-16"}]'::jsonb,NULL,25),
('k4schiebe','k',4,'k3oeff','Schiebetür: vor der Wand, in der Wand','Vor der Wand laufend ist sie ein sichtbares Möbel, in der Wand (Kastensystem) verschwindet sie ganz. Letzteres will früh entschieden sein: Der Kasten ersetzt die Wand.','Ehrliche Beratung gehört dazu: Schiebetüren dichten schlechter (Schall, Geruch, Licht) und die Beschlagsqualität entscheidet über die Freude am Bauteil. In-der-Wand-Systeme kollidieren mit Elektro und Sanitär in derselben Wand; Installationszonen früh koordinieren.',NULL,'{}'::text[],'[]'::jsonb,NULL,26),
('k4sonst','k',4,'k3oeff','Falt-, Pendel-, Drehtür','Sonderöffnungsarten für Sondersituationen: Falttüren für flexible Raumteilung, Pendeltüren für hochfrequente Durchgänge, Drehtüren als raumbildende Geste.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,27),
('k2a','k',2,'k1','Außen- und Haustüren','Die Haustür arbeitet härter als jede Innentür: Wärmeschutz, Schlagregen, Einbruchhemmung, Barrierefreiheit und Repräsentation in einem Bauteil. Entsprechend konfliktreich sind die Anforderungen untereinander.',NULL,NULL,ARRAY['x3haustuer','e2schwelle']::text[],'[]'::jsonb,NULL,28),
('k3waerme','k',3,'k2a','Aufbau und Wärmeschutz','Haustürblätter sind heute gedämmte Sandwichkonstruktionen; der energetische Schwachpunkt ist selten das Blatt, sondern Schwelle, Falz und Verglasungsränder.',NULL,NULL,'{}'::text[],'[]'::jsonb,'{"de":"Anforderungswerte über das GEG.","at":"Anforderungen über OIB-Richtlinie 6.","ch":"Anforderungen über MuKEn bzw. kantonale Energiegesetze."}'::jsonb,29),
('k3rc','k',3,'k2a','Einbruchschutz: RC-Klassen','RC 2 ist der übliche Wohnbaustandard. Entscheidend: Die Klasse gilt nur für das geprüfte Gesamtelement samt Montage, nicht für einzelne schöne Komponenten.',NULL,NULL,'{}'::text[],'[{"t":"DIN EN 1627 Einbruchhemmung: Widerstandsklassen","stand":"2021-11","u":"https://www.dinmedia.de/de/norm/din-en-1627/332355073","geprueft":"2026-08-16"}]'::jsonb,NULL,30);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('k3schwelle','k',3,'k2a','Schwelle und Barrierefreiheit','Hier kollidieren zwei berechtigte Welten: Die Abdichtung will Höhe, die Barrierefreiheit will null. Die Nullschwelle ist deshalb ein eigenes Planungsthema geworden.',NULL,NULL,ARRAY['e2schwelle']::text[],'[]'::jsonb,NULL,31),
('k4null','k',4,'k3schwelle','Nullschwelle: Abdichtung vs. Barrierefreiheit','Die Barrierefreiheits-Normen wollen maximal 2 cm Schwellenhöhe (und eigentlich gar keine), die Abdichtungsregeln wollen klassisch 15 cm Anschlusshöhe. Die Nullschwelle ist der planbare, aber aufwendige Kompromiss.','Funktionierende Nullschwellen sind ein System aus mehreren Verteidigungslinien: Entwässerungsrinne mit freiem Ablauf, Vordach oder Rücksprung als Schlagregenschutz, Gefälle vom Gebäude weg und ein geprüftes Schwellenprofil. Wer nur das Profil kauft und den Rest weglässt, plant den Wasserschaden mit.','Reduzierte Anschlusshöhen unter 15 cm gelten als Sonderkonstruktion und verlangen besondere Maßnahmen (Rinne, Überdachung, Gefälle ≥ 2 % vom Gebäude weg) sowie deren Dokumentation. Rinne mit Anschluss an die Entwässerung, nicht nur als Kiesstreifen. Ab hier: Fachregeln Abdichtung und Systemdetails des Schwellenherstellers.',ARRAY['kt3rampe']::text[],'[{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","stand":"2011-09","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","geprueft":"2026-08-16"},{"t":"DIN 18531-1 Abdichtung von Dächern, Balkonen und Loggien","stand":"2025-08","u":"https://www.dinmedia.de/de/norm/din-18531-1/391197155","geprueft":"2026-08-16"},{"t":"DIN 18533-1 Abdichtung von erdberührten Bauteilen","stand":"2026-06","u":"https://www.dinmedia.de/de/norm/din-18533-1/399850897","geprueft":"2026-08-16"},{"t":"Fachregel für Abdichtungen (Flachdachrichtlinie), ZVDH (weiterführend)","stand":"Ausgabe Januar 2026","u":"https://www.baunetzwissen.de/flachdach/fachwissen/richtlinien-verordnungen/fachregel-fuer-abdichtungen--flachdachrichtlinie-1323705","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 18040, bauordnungsrechtlich je Bundesland eingeführt.","at":"ÖNORM B 1600 und OIB-Richtlinie 4; 2-cm-Grenze analog.","ch":"SIA 500 „Hindernisfreie Bauten\"; Praxis-Doku der Fachstelle Hindernisfreie Architektur."}'::jsonb,32),
('k2f','k',2,'k1','Funktionstüren','Brand, Rauch, Schall, Strahlenschutz: Funktionstüren sind geprüfte Systeme, keine konfigurierbaren Möbel. Die wichtigste Planungsregel lautet: erst Anforderung klären, dann gestalten, nie umgekehrt.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,33),
('k3t30','k',3,'k2f','Brandschutztüren (T30/T60/T90)','Feuerschutzabschlüsse halten dem Feuer 30, 60 oder 90 Minuten stand und sind als Gesamtsystem zugelassen: Blatt, Zarge, Beschlag und Einbausituation gehören untrennbar zusammen.',NULL,NULL,ARRAY['kt3raum']::text[],'[]'::jsonb,NULL,34),
('k4t30z','k',4,'k3t30','Zulassung und Veränderungsverbot','An zugelassenen Feuerschutzabschlüssen darf nichts verändert werden: kein anderer Drücker, kein Kürzen, kein nachträglicher Anstrich außerhalb der Zulassung. Was verändert wird, verliert die Zulassung.',NULL,'Verwendbarkeitsnachweis (allgemeine bauaufsichtliche Zulassung bzw. europäisch CE mit Klassifizierung nach EN 13501-2, z. B. EI2 30) gehört in die Objektdokumentation. Kennzeichnungsschild am Element muss dauerhaft lesbar bleiben. Zulässiges Zubehör nur aus der Zulassung des Herstellers. Ab hier: Zulassungsbescheid des konkreten Elements lesen, immer.','{}'::text[],'[{"t":"DIN EN 13501-2 Klassifizierung Feuerwiderstand","stand":"2023-12","u":"https://www.dinmedia.de/de/norm/din-en-13501-2/367755282","geprueft":"2026-08-16"},{"t":"DIN 4102-5 (nationale Klassifizierung T30)","stand":"1977-09","u":"https://www.dinmedia.de/de/norm/din-4102-5/684345","geprueft":"2026-08-16"}]'::jsonb,'{"de":"T30 nach DIN 4102 bzw. EI2 30 europäisch; abZ/aBG des DIBt.","at":"EI2 30 nach OIB-Richtlinie 2; ÜA-Kennzeichnung.","ch":"EI30 nach VKF-Brandschutzvorschriften; VKF-Anerkennung statt DIBt-Zulassung."}'::jsonb,35),
('k3rs','k',3,'k2f','Rauchschutztüren (RS)','Rauchschutztüren begrenzen den Rauchdurchtritt (die eigentliche Todesursache bei Bränden) und brauchen dafür umlaufende Dichtungen, Bodendichtung und selbstschließende Beschläge.',NULL,NULL,'{}'::text[],'[{"t":"DIN 18095-1 Rauchschutztüren: Begriffe und Anforderungen","stand":"1988-10","u":"https://www.dinmedia.de/de/norm/din-18095-1/1397160","geprueft":"2026-08-16"},{"t":"DIN EN 1634-3 Prüfungen Rauchschutzabschlüsse","stand":"2005-01","u":"https://www.dinmedia.de/de/norm/din-en-1634-3/75986740","geprueft":"2026-08-16"}]'::jsonb,NULL,36),
('k3schall','k',3,'k2f','Schallschutztüren','Schallschutz entsteht aus Masse plus Dichtung: schweres Blatt, umlaufende Falzdichtungen, absenkbare Bodendichtung. Das Laborniveau erreicht die Baustelle nur bei perfekter Montage.',NULL,NULL,'{}'::text[],'[{"t":"DIN 4109-1 Schallschutz im Hochbau: Mindestanforderungen","stand":"2018-01","u":"https://www.dinmedia.de/de/norm/din-4109-1/280079001","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 4109, erhöhter Schallschutz über Beiblatt 2 / VDI 4100.","at":"ÖNORM B 8115.","ch":"SIA 181."}'::jsonb,37),
('k3kombi','k',3,'k2f','Kombinationsanforderungen','Der Klassiker im Objektbau: T30 + RS + Schallschutz + Barrierefreiheit an derselben Tür. Jede Einzelanforderung ist lösbar; die Kombination entscheidet, ob es das Element überhaupt gibt.','Vorgehen: Anforderungsmatrix je Tür aufstellen (Brand, Rauch, Schall, RC, Barrierefreiheit, Feuchtraum), dann gegen reale Herstellerprogramme prüfen, bevor die Tür im Grundriss fixiert wird. Die teuersten Türen im Projekt sind fast immer Kombinationselemente, die zu spät als solche erkannt wurden. Absenkdichtung vs. Rauchschutz vs. Nullschwelle ist der häufigste Zielkonflikt.','Praxisfalle Barrierefreiheit: DIN 18040 begrenzt Bedienkräfte (Klasse 3 nach EN 12217 empfohlen); Türschließer an T30-RS-Elementen überschreiten das schnell. Lösung meist Freilauftürschließer mit Feststellanlage (dann Rauchmelderpflicht am Sturz). Ab hier: Herstellerberatung mit vollständiger Anforderungsmatrix.','{}'::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","stand":"2010-10","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","stand":"2011-09","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","geprueft":"2026-08-16"},{"t":"DIN EN 12217 Türen: Bedienungskräfte","stand":"2015-07","u":"https://www.dinmedia.de/de/norm/din-en-12217/233402452","geprueft":"2026-08-16"}]'::jsonb,NULL,38),
('k2b','k',2,'k1','Türen im Bestand','Bestandstüren sind Zeitzeugen und Problembauteile zugleich: oft schöner als jeder Neubaustandard, aber ohne Schall-, Brand- oder Einbruchwerte. Die Frage ist fast nie ob, sondern wie viel Ertüchtigung.',NULL,NULL,ARRAY['x1']::text[],'[]'::jsonb,NULL,39),
('k3hist','k',3,'k2b','Aufarbeitung historischer Türen','Aufarbeiten heißt: Substanz sichern, Funktion wiederherstellen, Patina bewahren. Häufig günstiger als gedacht und fast immer nachhaltiger als der Austausch.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,40),
('k3ertuecht','k',3,'k2b','Ertüchtigung im Denkmal','Schall- und Brandertüchtigung historischer Türen bewegt sich zwischen Auflagen und Substanzschutz: aufgedoppelte Blätter, eingefräste Dichtungen, Kastentür-Prinzip als zweite Ebene.',NULL,NULL,ARRAY['x4lernen']::text[],'[]'::jsonb,NULL,41),
('e1','e',1,NULL,'Die Tür als Entwurfselement','Bevor die Tür ein Bauteil ist, ist sie eine räumliche Behauptung: Sie entscheidet, wie Übergänge erlebt werden, wie Räume sich zueinander verhalten und wo ein Gebäude seine Bewohner berührt. Diese Perspektive versammelt das gestalterische Wissen zur Tür.',NULL,NULL,ARRAY['k1','x3haustuer']::text[],'[]'::jsonb,NULL,42),
('e2schwelle','e',2,'e1','Schwelle und Übergang','Die Tür markiert den Wechsel zwischen Sphären: außen und innen, öffentlich und privat, laut und still. Wie dieser Wechsel gestaltet ist (abrupt, gestuft, gedehnt), gehört zu den ältesten Themen der Architektur.',NULL,NULL,ARRAY['k3schwelle','x3tor']::text[],'[]'::jsonb,NULL,43),
('e3zaesur','e',3,'e2schwelle','Die Tür als räumliche Zäsur','Türen trennen nicht nur Räume, sie inszenieren den Übergang. Ob ein Wechsel abrupt oder gestuft erfolgt (Tür in der Wandflucht oder in einer Nische), verändert, wie privat sich der Raum dahinter anfühlt.','Entwurflich lässt sich die Zäsur über vier Register steuern: Position (Wandflucht vs. Laibungstiefe), Format (Normhöhe vs. raumhoch), Artikulation (gerahmt vs. flächenbündig) und Material- oder Lichtwechsel am Übergang. Eine tiefe Laibung verlangsamt den Übergang; eine flächenbündige Tür lässt ihn beiläufig werden. Die Entscheidung sollte aus der Raumsequenz begründet sein, nicht aus dem Katalog. Referenzen: Loos’ Raumplan, Zumthors gestufte Schwellen, die Torsituationen der Margarethenhöhe im Siedlungsmaßstab.',NULL,'{}'::text[],'[]'::jsonb,NULL,44),
('e3schwellenr','e',3,'e2schwelle','Schwellenräume: Windfang, Vorraum, Nische','Zwischen draußen und drinnen kann ein eigener Raum liegen: Der Windfang ist Klimapuffer und Zeremonie zugleich. Wo er wegrationalisiert wird, verliert das Ankommen seine Zeit.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,45);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('e2prop','e',2,'e1','Proportion und Format','Ob eine Tür 198,5 cm oder raumhoch ist, entscheidet über die Wand, in der sie steht: Die Normtür bleibt Loch in der Fläche, die raumhohe Tür macht die Wand zur Abfolge von Ebenen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,46),
('e3raumhoch','e',3,'e2prop','Raumhohe Türen und der aufgelöste Sturz','Ohne Sturz verliert die Tür ihr Über-Kopf-Gewicht und der Raum fließt durch die Öffnung weiter. Konstruktiv heißt das: schwerere Blätter, stärkere Bänder, präzisere Toleranzen.','Der Effekt trägt nur, wenn er konsequent ist: Raumhohe Türen verlangen raumhohe Disziplin auch bei Schränken, Verglasungen und Durchgängen derselben Raumfolge. Einzeln eingesetzt wirken sie schnell wie ein Ausstattungsmerkmal. Kostenseitig sind Blattgewicht und Bänderqualität die Treiber, nicht die Blattlänge.',NULL,ARRAY['k6trocken']::text[],'[]'::jsonb,NULL,47),
('e3breite','e',3,'e2prop','Türbreiten zwischen Norm und Geste','88,5 cm Durchgang sind Funktion; 1,20 m sind eine Einladung, zweiflügelig ist ein Ereignis. Breite ist das einfachste Mittel, Hierarchien in einer Raumfolge zu markieren.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,48),
('e2artik','e',2,'e1','Artikulation vs. Verschwinden','Die Grundsatzentscheidung der Türgestaltung: Wird die Tür betont (Portal, Rahmung, Gewände) oder zum Verschwinden gebracht (flächenbündig, wandfarbig, schattenfugengeführt)? Beides sind starke Haltungen; nur das Ungefähre dazwischen ist schwach.',NULL,NULL,ARRAY['k3zarge']::text[],'[]'::jsonb,NULL,49),
('e3portal','e',3,'e2artik','Die betonte Tür: Portal, Rahmung, Gewände','Die gerahmte Tür adelt den Durchgang: vom Werksteingewände bis zum farbig abgesetzten Zargenspiegel. Rahmung sagt: Hier passiert etwas Wichtiges.',NULL,NULL,ARRAY['x4bogen']::text[],'[]'::jsonb,NULL,50),
('e4spiegelgest','e',4,'e3portal','Der Zargenspiegel als gestalterisches Mittel','Das kleinste Portal der Welt: Schon mit Breite, Farbe und Kantenprofil des Zargenspiegels lässt sich eine Standardtür betonen oder beruhigen, ohne das Budget zu sprengen.','Drei Strategien: (1) Spiegel in Wandfarbe streichen lassen und die Tür zurücknehmen. (2) Spiegel kontrastieren (dunkler Ton auf heller Wand) und die Öffnung als Rahmen zeigen. (3) Spiegel überbreit als moderne Interpretation des Gewändes einsetzen. Alle drei kosten fast nichts; sie erfordern nur eine frühe Festlegung im Türtypenblatt.',NULL,ARRAY['k5spiegel']::text[],'[]'::jsonb,NULL,51),
('e3unsichtbar','e',3,'e2artik','Die unsichtbare Tür','Flächenbündig, tapezierbar, wandfarbig, ohne sichtbare Bänder: Die Tür als Geheimnis der Wand. Sie funktioniert nur mit hoher Präzision; jede sichtbare Toleranz zerstört die Illusion.',NULL,NULL,ARRAY['k4verdeckt','k4falz']::text[],'[]'::jsonb,NULL,52),
('e2hand','e',2,'e1','Die Tür als Berührungspunkt','Die Tür ist der Ort, an dem Architektur physisch berührt wird, jeden Tag, von jeder Hand. Kein anderes Bauteil rechtfertigt Materialqualität so unmittelbar.',NULL,NULL,ARRAY['k3besch','kt3hand']::text[],'[]'::jsonb,NULL,53),
('e3druecker','e',3,'e2hand','Der Drücker als Handschlag des Gebäudes','Ein Türdrücker ist das Bauteil mit dem intensivsten Körperkontakt im ganzen Haus. Gewicht, Temperatur des Materials und die Rückstellung beim Loslassen bilden zusammen den Charakter dieses Handschlags.','Materiallogik: Messing und Bronze altern mit der Benutzung und erzählen sie weiter; Edelstahl bleibt neutral und dienstbar; beschichtete Leichtmetalle fühlen sich nach wenig an, egal wie sie aussehen. Prominente Fälle (Wittgensteins Türklinke, die Drücker von Chareau) zeigen, wie viel Entwurfsernst in dieses kleinste Element passt.',NULL,ARRAY['k4drueck']::text[],'[]'::jsonb,NULL,54),
('e2folge','e',2,'e1','Türen in der Raumfolge','Türen sind die Gelenke einer Raumsequenz: Ihre Lage entscheidet, ob Räume gereiht, verschachtelt oder verschliffen wirken.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,55),
('e3enfilade','e',3,'e2folge','Enfilade und Sichtachse','Liegen Türen mehrerer Räume auf einer Achse, entsteht die Enfilade: Tiefe, Durchblick, Versprechen. Ein barockes Prinzip, das auch im Wohnungsbau funktioniert, wenn man es sich traut.',NULL,NULL,ARRAY['et2prom']::text[],'[]'::jsonb,NULL,56),
('e3position','e',3,'e2folge','Türposition im Raum: Ecke oder Mitte','Die Tür in der Raumecke erschließt effizient und lässt Stellflächen frei; die Tür in der Wandmitte teilt den Raum, macht ihn aber zeremonieller. Eine der stillsten, folgenreichsten Grundrissentscheidungen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,57),
('x1','x',1,NULL,'Margarethenhöhe, Essen','Georg Metzendorfs Gartenstadt (ab 1909, gestiftet von Margarethe Krupp) gilt als eine der schönsten Siedlungen Deutschlands: serielle Typen, handwerkliche Details und ein Städtebau, der Gemeinschaft räumlich formuliert. Hier als Fallstudie erschlossen: vom Siedlungsmaßstab bis zum Türgriff.',NULL,NULL,ARRAY['e1','k1']::text[],'[{"t":"Ruhr Museum: Die Gartenstadt Margarethenhöhe (weiterführend)","u":"https://ruhrmuseum.de/ausstellungen/aktuell/die-gartenstadt-margarethenhoehe","geprueft":"2026-08-16"},{"t":"Rainer Metzendorf: Georg Metzendorf 1874–1934. Siedlungen und Bauten (Literatur)","stand":"Darmstadt/Marburg 1994, ISBN 3-88443-185-4","geprueft":"2026-08-16"}]'::jsonb,NULL,58),
('x2staedt','x',2,'x1','Städtebau der Gartenstadt','Gekrümmte Straßen, gestaffelte Plätze, ein bewusster Bruch mit dem Mietskasernenraster: Die Margarethenhöhe übersetzt die englische Gartenstadtidee in eine rheinisch-westfälische Handschrift.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,59),
('x3tor','x',3,'x2staedt','Torhaus und Brückenzugang','Man betritt die Margarethenhöhe über eine Brücke und durch ein Torhaus: Die ganze Siedlung hat eine Tür. Der Schwellenmoment, den ein Hauseingang im Kleinen leistet, wird hier im Maßstab des Quartiers durchgespielt.',NULL,NULL,ARRAY['e2schwelle','e3zaesur']::text[],'[]'::jsonb,NULL,60);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('x3platz','x',3,'x2staedt','Platzfolgen und Straßenräume','Der kleine Markt als Herzstück, Straßen, die sich weiten und verengen: Raumfolge als städtebauliches Erzählen, lange bevor der Begriff Sequenzierung erfunden war.',NULL,NULL,ARRAY['et2prom']::text[],'[]'::jsonb,NULL,61),
('x2typ','x',2,'x1','Gebäudetypen','Wenige Haustypen, viele Varianten: Metzendorf zeigt, wie Serie und Individualität zusammengehen, eine Frage, die der heutige Wohnungsbau dringlicher stellt als je.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,62),
('x3reihe','x',3,'x2typ','Reihenhaustypen und ihre Variation','Gleiche Grundrisse, variierte Giebel, Erker, Dachformen und Eingänge: Die Variation sitzt an den Rändern des Typs, nicht in seinem Kern. Ein ökonomisches Prinzip mit großer Wirkung.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,63),
('x2fass','x',2,'x1','Fassadenelemente','Putzflächen, Klinkersockel, Fensterläden, Haustüren: Die Fassaden der Margarethenhöhe arbeiten mit einem kleinen, präzise eingesetzten Vokabular. Das wichtigste Wort darin ist der Hauseingang.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,64),
('x3haustuer','x',3,'x2fass','Haustüren der Margarethenhöhe','Die Haustür ist das Schmuckstück der ansonsten sparsamen Fassaden: gerahmt, farbig, handwerklich detailliert. Sie trägt die Identität des einzelnen Hauses innerhalb der Serie.',NULL,NULL,ARRAY['k2a','e3portal']::text[],'[]'::jsonb,NULL,65),
('x4bogen','x',4,'x3haustuer','Rundbogenportale und Türgewände','Metzendorf setzte Haustüren fast nie nackt in die Wand: Rundbogen und Werksteingewände machen den Eingang zum wichtigsten Ereignis der Fassade.','Das Prinzip ist übertragbar: serielle Typen plus individualisierte Schwelle gleich Identifikation ohne Beliebigkeit. Die Portale variieren in wenigen kontrollierten Parametern (Bogenform, Gewändematerial, Türfarbe), während Typengrundriss und Fassadenaufbau konstant bleiben. Für heutige Reihenhaus- und Geschossprojekte ein präzises Rezept gegen die Monotonie-Kritik.',NULL,ARRAY['e3portal']::text[],'[]'::jsonb,NULL,66),
('x4farbe','x',4,'x3haustuer','Farbigkeit und Handwerksdetail','Türblätter in kräftigen Farben, Beschläge als Handwerksstücke: Die Margarethenhöhe zeigt, dass Farbe an der Tür kein Risiko ist, sondern ein System, wenn die Palette siedlungsweit kuratiert wird.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,67),
('x4lernen','x',4,'x3haustuer','Was heutige Planung daraus lernt','Drei Lehren: Eingänge sind der richtige Ort für Individualität in der Serie. Wenige Parameter, konsequent variiert, schlagen viele Parameter beliebig gemischt. Und: Handwerkliches Detail am Berührungspunkt zahlt sich über Jahrzehnte aus.','Die Rückübersetzung in heutige Praxis führt direkt zu den Konstruktionsfragen: Wie verträgt sich ein gerahmtes Portal mit RC-2-Anforderung und Nullschwelle? Wie ersetzt man Werkstein durch heutige Budgets (Betonfertigteil, Klinkerrahmung, farbige Laibung)? Die Fallstudie endet dort, wo die Bauteilebene beginnt.',NULL,ARRAY['k2a','k4null','e2artik']::text[],'[]'::jsonb,NULL,68),
('kt1','k',1,NULL,'Treppen','Die Treppe ist das einzige Bauteil, das der Körper vollständig durchmisst: Jede Abweichung im Steigungsverhältnis spürt man im Schritt. Zugleich ist sie Rettungsweg, Tragwerk und oft die teuerste Einzelposition des Rohbaus. Das Themenfeld gliedert sich in Geometrie, Konstruktion, Absturzsicherung und Baurecht.',NULL,NULL,ARRAY['et1','k1']::text[],'[]'::jsonb,NULL,69),
('kt2geo','k',2,'kt1','Laufgeometrie und Podeste','Bevor eine Treppe Material hat, hat sie Geometrie: Steigungsverhältnis, Lauflinie, Podeste, Kopfhöhen. Diese Maße entscheiden über Bequemlichkeit und Genehmigungsfähigkeit, und sie sind später fast nicht mehr korrigierbar.','Der häufigste Planungsfehler ist nicht die falsche Formel, sondern die zu knapp geschnittene Rohbauöffnung: Wer die Treppe erst in der Ausführungsplanung ernst nimmt, verbaut sich Steigungsverhältnis und Kopfhöhe gleichzeitig. Treppenloch und Geschosshöhe gehören in LP 2 zusammen entworfen.',NULL,'{}'::text[],'[]'::jsonb,NULL,70),
('kt3steig','k',3,'kt2geo','Steigungsverhältnis und Schrittmaß','Das Verhältnis von Steigung zu Auftritt bestimmt, ob eine Treppe bequem, sportlich oder gefährlich ist. Die klassische Schrittmaßregel: zwei Steigungen plus ein Auftritt sollen etwa einer Schrittlänge entsprechen. Eine Wohnhaustreppe mit 18/27 geht mühelos, eine mit 20/23 spürt man in den Knien.','Bequemlichkeit entsteht nicht nur aus der Formel: Konstante Steigungen über alle Läufe (auch am Übergang zum Belag!), ausreichende Auftrittstiefe in der Lauflinie bei gewendelten Treppen und ein Antritt ohne Sonderformat zählen mehr als die dritte Nachkommastelle. Der klassische Baufehler ist die abweichende erste oder letzte Steigung, weil der Bodenaufbau zweier Geschosse verschieden ausfiel; das ist auch ein Unfallrisiko.','Schrittmaßregel 2s + a = 59 bis 65 cm. Wohngebäude (notwendige Treppe): Steigung max. ca. 19 cm, Auftritt min. ca. 26 cm; bequemer Wohnstandard 17/29. Öffentliche Gebäude strenger, Auftritt eher ≥ 29 cm. Steigungen innerhalb eines Laufs müssen gleich sein; Toleranz wenige Millimeter. Werte sind länderabhängig (siehe DACH-Kasten). Ab hier: DIN 18065 in aktueller Ausgabe plus Landesbauordnung des Projekts.',ARRAY['et2prom']::text[],'[{"t":"DIN 18065 Gebäudetreppen","stand":"2020-08","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","geprueft":"2026-08-16"},{"t":"Landesbauordnung (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-16"},{"t":"Baunetzwissen Treppen (weiterführend)","u":"https://www.baunetzwissen.de/treppen","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 18065 plus Landesbauordnung; Maße unterscheiden sich je Bundesland und Gebäudeklasse.","at":"ÖNORM B 5371 und OIB-Richtlinie 4; Hauptreppen 18/27 als Leitwert.","ch":"Keine zwingende Norm-Treppe; SIA 500 für Hindernisfreiheit, bfu-Fachdokumentation als anerkannte Regel; 17/29 üblich."}'::jsonb,71),
('kt3form','k',3,'kt2geo','Grundformen: gerade, gewendelt, gewunden','Gerade Läufe sind bequem und möblierbar, gewendelte Treppen sparen Fläche und erkaufen das mit verzogenen Stufen, Spindeltreppen sind das Minimum an Fläche und Komfort. Die Form ist zuerst eine Grundriss-, dann eine Kostenentscheidung.','Beim Verziehen gewendelter Treppen entscheidet die Auftrittsbreite an der schmalen Seite über die reale Begehbarkeit; großzügig verzogene Viertelwendelungen gehen fast wie gerade Läufe. Für Umzüge und Möbeltransport ist die halbgewendelte Treppe ohne Zwischenpodest der heimliche Ärgernis-Klassiker; ein Podest kostet Fläche und rettet Rücken.',NULL,ARRAY['et2skulptur']::text[],'[]'::jsonb,NULL,72),
('kt3podest','k',3,'kt2geo','Podeste, Antritt, Austritt','Podeste sind die Pausen der Treppe: baurechtlich gefordert ab bestimmten Stufenzahlen, entwurflich die Orte, an denen eine Treppe Blickwechsel und Begegnung organisiert.',NULL,'Zwischenpodest üblicherweise nach max. 18 Steigungen (länderabhängig). Podesttiefe mindestens Laufbreite, besser Laufbreite plus ein Auftritt. Türen dürfen nicht in den Lauf aufschlagen; vor Türen am Podest Mindesttiefen freihalten. Ab hier: DIN 18065 und Landesbauordnung.',ARRAY['et2ort']::text[],'[{"t":"DIN 18065 Gebäudetreppen","stand":"2020-08","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","geprueft":"2026-08-16"}]'::jsonb,NULL,73),
('kt3kopf','k',3,'kt2geo','Kopfhöhe und Durchgangshöhe','Zwei Meter lichte Höhe über der Vorderkante jeder Stufe sind das übliche Minimum. Der kritische Punkt liegt fast immer an der Deckenkante des Treppenlochs, und er entscheidet über die Länge der Öffnung.',NULL,'Lichte Durchgangshöhe min. 2,00 m, lotrecht über den Stufenvorderkanten gemessen. Bei Dachgeschossen zusätzlich die Schrägen prüfen; die Kopfhöhe entlang der gesamten Lauflinie, nicht nur am Austritt. Ab hier: DIN 18065 und Maßkontrolle am Rohbau.','{}'::text[],'[{"t":"DIN 18065 Gebäudetreppen","stand":"2020-08","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","geprueft":"2026-08-16"}]'::jsonb,NULL,74),
('kt2konst','k',2,'kt1','Konstruktionen nach Material','Beton trägt und dämpft, Holz erzählt vom Handwerk, Stahl macht Treppen leicht und filigran. Die Materialwahl legt Kosten, Schallschutz, Bauablauf und Ausstrahlung gleichzeitig fest.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,75);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kt3beton','k',3,'kt2konst','Stahlbetontreppen','Die Ortbeton- oder Fertigteiltreppe ist der Standard im Geschossbau: robust, massearm im Schwingen, früh im Bauablauf begehbar. Ihre kritische Stelle ist nicht die Statik, sondern der Trittschall.','Fertigteilläufe dominieren, weil sie Maßhaltigkeit und Tempo bringen und die Untersicht schalungsglatt liefern. Planungsentscheidend ist früh: sichtbar belassen (dann Fertigteilqualität und Fasen definieren) oder belegt. Der Rohbau muss die Auflagerdetails der Schallentkopplung kennen, bevor die Decke geschalt wird.',NULL,ARRAY['et2skulptur']::text[],'[]'::jsonb,NULL,76),
('kt4schall','k',4,'kt3beton','Trittschallentkopplung','Eine starr angeschlossene Treppe telefoniert jeden Schritt ins Nachbargeschoss. Entkoppelt wird an Auflagern und Podestanschlüssen mit Elastomerlagern, nicht nachträglich mit Belag.',NULL,'Tragende Anschlüsse über geprüfte Trittschalldämmelemente (Elastomer- bzw. bewehrte Lager) an Lauf- und Podestauflagern; Fugen zu Wänden konsequent freihalten, kein Mörtel- oder Estrichkontakt (klassische Schallbrücke). Nachweis im Schallschutzkonzept führen. Ab hier: Systemzulassung des gewählten Lagers und Detailblätter.','{}'::text[],'[{"t":"DIN 4109-1 Schallschutz im Hochbau: Mindestanforderungen","stand":"2018-01","u":"https://www.dinmedia.de/de/norm/din-4109-1/280079001","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 4109; erhöhter Schallschutz vertraglich klären.","at":"ÖNORM B 8115.","ch":"SIA 181, Anforderungen „erhöht\" im Mehrfamilienhaus üblich."}'::jsonb,77),
('kt3holz','k',3,'kt2konst','Holztreppen','Eingestemmt, aufgesattelt oder mit Wangen aus Werkstoffplatten: Die Holztreppe ist die Treppe des Einfamilien- und Bestandsbaus. Sie knarrt nur, wenn sie schlecht gefügt ist.','Die relevanten Entscheidungen: Hartholz für Trittstufen (Buche, Eiche) gegen Weichholz-Charme; geschlossene oder offene Setzstufen (offen wirkt leichter, sammelt aber Anforderungen an die Öffnungsmaße der Absturzsicherung); Verbindung zur Wand (sichtbare Wange oder aufgesattelt frei). Im Bestand ist die knarrende Treppe meist ein Fall für Nachspannen und Verleimen, nicht für Austausch.',NULL,'{}'::text[],'[]'::jsonb,NULL,78),
('kt3stahl','k',3,'kt2konst','Stahl- und Spindeltreppen','Gefaltetes Blech, Wangen aus Flachstahl oder die Spindel um ein Rohr: Stahl kann Treppen, die kaum da sind. Der Preis sind Schwingung, Dröhnen und Brandschutzfragen im Innenraum.','Gegen das Dröhnen helfen ausbetonierte oder mit Holz belegte Stufen und ausreichende Blechstärken; gegen Schwingung ein ehrlicher statischer Nachweis statt Gefühl. Sichtbare Schweißnähte und Kanten definieren die Qualität, deshalb Werkstattfertigung und Musterstück vereinbaren.',NULL,'{}'::text[],'[]'::jsonb,NULL,79),
('kt3fertig','k',3,'kt2konst','System- und Raumspartreppen','Vom Katalogbausatz bis zur Samba-Treppe: Systemtreppen lösen Budget- und Platzprobleme und sind fast nie die schönste Antwort. Raumspartreppen sind baurechtlich nur als Zusatztreppe zulässig, nicht als notwendige.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,80),
('kt2gel','k',2,'kt1','Geländer und Handläufe','Das Geländer ist Absturzsicherung mit Rechtsfolgen, der Handlauf ist Ergonomie mit Gestaltungsanspruch. Beide werden regelmäßig verwechselt und beide zu spät geplant.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,81),
('kt3gelh','k',3,'kt2gel','Geländerhöhen und Öffnungsmaße','Die Höhe der Absturzsicherung und die maximale Öffnungsweite (Stichwort Kinderkopf) sind harte baurechtliche Werte, die sich zwischen den Ländern unterscheiden. Gestalterische Freiheit beginnt erst innerhalb dieser Maße.',NULL,'Übliche Werte: Geländerhöhe 90 cm bis 12 m Absturzhöhe, darüber 110 cm (DE, je Landesbauordnung); Öffnungen so, dass eine Kugel von 12 cm nicht durchpasst, im Wohnungsbau teils entschärft. Horizontale, bekletterbare Füllungen sind in Kindernutzung zu vermeiden. Werte länderabhängig (siehe DACH-Kasten). Ab hier: Landesbauordnung bzw. nationale Regel des Projektstandorts.','{}'::text[],'[{"t":"Landesbauordnungen (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-16"},{"t":"DIN 18065 Gebäudetreppen","stand":"2020-08","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","geprueft":"2026-08-16"}]'::jsonb,'{"de":"LBO-abhängig; 90/110-cm-Systematik verbreitet.","at":"OIB-Richtlinie 4: 100 cm ab 60 cm Absturzhöhe, 110 cm über 12 m.","ch":"SIA 358 „Geländer und Brüstungen\": 100 cm Leitwert, Öffnungsregeln eigenständig."}'::jsonb,82),
('kt3hand','k',3,'kt2gel','Handlauf: Ergonomie und Pflicht','Der Handlauf ist der Türdrücker der Treppe: das Bauteil, das jede Hand kennt. Greifbarkeit schlägt Grafik; ein schöner Flachstahl, den keine Hand umschließen kann, ist ein Formfehler.','Ergonomisch bewährt: runde oder oval-runde Profile etwa 3 bis 4,5 cm stark, Höhe um 85 bis 90 cm, durchlaufend auch an Podesten und am An- und Austritt waagerecht weitergeführt (etwa 30 cm), Abstand zur Wand ausreichend für die geschlossene Hand. Barrierefreie Gebäude verlangen beidseitige Handläufe und teils taktile Informationen. Material am Griff ehrlich wählen: Holz und Metall altern verschieden schön.',NULL,ARRAY['e2hand']::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","stand":"2010-10","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","stand":"2011-09","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 18040-1/-2 je Nutzung.","at":"ÖNORM B 1600.","ch":"SIA 500."}'::jsonb,83),
('kt3fuell','k',3,'kt2gel','Füllungen: Stab, Fläche, Netz','Stabgeländer sind die robuste Klassik, Glas- und Lochblechfüllungen machen Flächen, Seilnetze machen Leichtigkeit. Jede Wahl zieht eigene Befestigungs- und Prüffragen nach sich.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,84),
('kt2not','k',2,'kt1','Notwendige Treppen und Fluchtwege','Sobald eine Treppe Rettungsweg ist, wechselt sie die Disziplin: Aus Entwurf wird Baurecht. Laufbreiten, Treppenraum und Türen in den Treppenraum sind dann keine Geschmacksfragen mehr.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,85),
('kt3nutz','k',3,'kt2not','Nutzbare Laufbreite','Die nutzbare Breite wird zwischen den fertigen Oberflächen gemessen, Handläufe ragen begrenzt hinein. Notwendige Treppen brauchen mehr Breite als Komforttreppen im eigenen Haus.',NULL,'Notwendige Treppen im Wohnungsbau üblich min. 100 cm nutzbar (länderabhängig, teils 90), innerhalb einer Wohnung ca. 80 cm zulässig; Versammlungs- und Sonderbauten nach eigener Systematik (Bemessung nach Personenzahl). Einengungen durch Handläufe nur in definiertem Maß. Ab hier: Landesbauordnung bzw. Sonderbauvorschrift.','{}'::text[],'[{"t":"DIN 18065 Gebäudetreppen","stand":"2020-08","u":"https://www.dinmedia.de/de/norm/din-18065/322316050","geprueft":"2026-08-16"},{"t":"Landesbauordnungen / Sonderbauvorschriften (DE), exemplarisch BauO NRW 2018","stand":"Fassung 2018, zuletzt geändert Juli 2026","u":"https://recht.nrw.de/lmi/owa/br_bes_text?anw_nr=2&bes_id=39224&aufgehoben=N&keyword=landesbauordnung","geprueft":"2026-08-16"}]'::jsonb,'{"de":"LBO-abhängig.","at":"OIB-Richtlinie 4.","ch":"VKF-Brandschutzvorschriften und kantonale Regeln."}'::jsonb,86),
('kt3raum','k',3,'kt2not','Der notwendige Treppenraum','Der Treppenraum ist die vertikale Brandschutzzone des Hauses: eigene Wände, definierte Türen, Rauchableitung. Seine Logik bestimmt ganze Grundrisse, lange bevor über Stufen geredet wird.','Entwurflich ist der Treppenraum die Stelle, an der Brandschutz Grundrisse formt: Lage an der Außenwand (Fenster zur Rauchableitung) gegen innenliegend (Druckbelüftung oder RWA über Dach), Abschlüsse zu Nutzungseinheiten als klassifizierte Türen, keine Brandlasten im Raum. Wer den Treppenraum früh richtig setzt, erspart sich später die teuren Kompensationen.',NULL,ARRAY['k3t30']::text[],'[]'::jsonb,NULL,87),
('kt3aussen','k',3,'kt2not','Außentreppen als Rettungsweg','Die außenliegende Stahltreppe ist der pragmatische zweite Rettungsweg des Bestands: baurechtlich dankbar, gestalterisch selten geliebt, und im Winter ein Rutschthema mit Wartungspflicht.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,88),
('kt2rampe','k',2,'kt1','Rampen und Aufzüge','Wo Stufen sind, braucht es für die barrierefreie Erschließung eine zweite Antwort: Rampe oder Aufzug. Beide sind eigene Gewerke mit eigener Geometrie, hier als Schnittstellenwissen erschlossen.',NULL,NULL,'{}'::text[],'[]'::jsonb,NULL,89),
('kt3rampe','k',3,'kt2rampe','Rampen','Sechs Prozent Steigung fühlen sich zu Fuß nach nichts an und sind im Rollstuhl bereits Arbeit. Rampen brauchen überraschend viel Länge, und genau daran scheitern nachträgliche Lösungen.',NULL,'Barrierefreie Rampen: max. 6 % Längsgefälle, kein Quergefälle, Zwischenpodest (min. 150 cm) nach max. 600 cm Lauf, beidseitige Handläufe und Radabweiser, Bewegungsflächen an Anfang und Ende. Kürzere steilere Rampen sind keine barrierefreien Rampen, sondern Schiebehilfen. Ab hier: DIN 18040 bzw. nationale Regel plus Entwässerungsdetail bei Außenrampen.',ARRAY['k4null']::text[],'[{"t":"DIN 18040-1 Barrierefreies Bauen: öffentlich zugängliche Gebäude","stand":"2010-10","u":"https://www.dinmedia.de/de/norm/din-18040-1/133692028","geprueft":"2026-08-16"},{"t":"DIN 18040-2 Barrierefreies Bauen: Wohnungen","stand":"2011-09","u":"https://www.dinmedia.de/de/norm/din-18040-2/142706210","geprueft":"2026-08-16"}]'::jsonb,'{"de":"DIN 18040.","at":"ÖNORM B 1600: gleiche Systematik, teils abweichende Maße.","ch":"SIA 500: Leitwert ebenfalls 6 %, Details eigenständig."}'::jsonb,90);
insert into public.nodes (id,perspective,level,parent_id,title,t1,t2,t3,links,sources,dach,ord) values
('kt3aufzug','k',3,'kt2rampe','Aufzüge: Schacht und Schnittstellen','Für den Architekten ist der Aufzug vor allem ein Rohbauthema: Schachtmaße, Schachtkopf, Grube, Türlage und die Schallschutzfuge zum Wohnraum. Die Kabine wählt man aus dem Katalog, den Schacht nicht.','Früh festzulegen: Durchgangs- oder Übereck-Ladung, Türbreite (barrierefreie Kabinenmaße!), Schachtkopf- und Grubenhöhen des gewählten Systems, Maschinenraumlos ja/nein, und die Entkopplung des Schachts von schutzbedürftigen Räumen. Der Klassiker unter den Konflikten: Aufzug direkt an Schlafzimmerwand.',NULL,'{}'::text[],'[]'::jsonb,NULL,91),
('et1','e',1,NULL,'Die Treppe als Entwurfselement','Keine andere Bewegung durchs Haus wird so choreographiert wie das Steigen: Die Treppe verteilt nicht nur Geschosse, sie inszeniert Ankommen, Sehen und Gesehenwerden. Diese Perspektive versammelt das gestalterische Wissen zur Treppe.',NULL,NULL,ARRAY['kt1','e1']::text[],'[]'::jsonb,NULL,92),
('et2skulptur','e',2,'et1','Die Treppe als Raumskulptur','Frei in den Raum gestellt, wird die Treppe vom Verkehrsbauwerk zum Möbel des Hauses: ein gefaltetes Band, eine Spindel, eine schwebende Läuferfolge. Der Auftritt kostet Fläche und will sie wert sein.','Die skulpturale Treppe funktioniert nur mit konstruktiver Disziplin: Untersicht, Kantenradius und Materialstoß sind ihre eigentlichen Entwurfsthemen, nicht die große Geste. Wer die Untersicht nicht zeichnet, bekommt eine Schalungsdokumentation statt einer Skulptur. Und sie braucht Luft: Eine Skulptur an drei Wänden ist ein Flurmöbel.',NULL,ARRAY['kt3beton','kt3stahl']::text[],'[]'::jsonb,NULL,93),
('et2prom','e',2,'et1','Promenade: Steigen als Sequenz','Die Rampe im Zentrum, die Treppe am Licht entlang, der Umweg mit Aussicht: Steigen kann ein Erzählstrang durchs Gebäude sein, nicht nur seine schnellste Vertikale.','Die klassische Referenz ist Corbusiers promenade architecturale, aber das Prinzip ist älter und alltagstauglicher: Wer beim Steigen etwas sieht (einen Hof, ein Oberlicht, die Straße), erlebt Geschosse als Abfolge von Orten statt als Etagen. Praktisch heißt das: Treppen an Fassaden und Lufträume legen, Podeste als Blickpunkte schneiden, und den Aufzug bewusst unattraktiver machen als den Weg.',NULL,ARRAY['kt3steig','e3enfilade','x3tor']::text[],'[]'::jsonb,NULL,94),
('et2ort','e',2,'et1','Die Treppe als Ort','Sitzstufen, Tribünen, das breite Podest mit Fenster: Treppen können Aufenthaltsorte sein, an denen man verabredet ist, wartet, zuschaut. Dann gelten zwei Regelwerke gleichzeitig: das des Steigens und das des Bleibens.','Sitzstufen brauchen andere Maße als Gehstufen (doppelte bis dreifache Steigung, tiefe Auftritte) und eine saubere Trennung oder Überlagerungslogik zur begehbaren Zone, sonst kollidieren Aufenthalt und Rettungsweg. Der Erfolg solcher Orte hängt an Licht, Blickrichtung und daran, ob dort wirklich jemand sitzen will; die Tribüne ohne Programm ist die teuerste Leerfläche des Hauses.',NULL,ARRAY['kt3podest','x3platz']::text[],'[]'::jsonb,NULL,95),
('et2licht','e',2,'et1','Treppe und Licht','Das Treppenauge unterm Oberlicht ist der älteste Lichtschacht der Baugeschichte: Steigen zum Licht ist eine körperliche Erfahrung, die kein Flur ersetzen kann. Umgekehrt bleibt die dunkle Treppe der unbeliebteste Raum des Hauses.',NULL,NULL,ARRAY['kt3kopf']::text[],'[]'::jsonb,NULL,96),
('et2zeigen','e',2,'et1','Treppen zeigen oder verbergen','Die repräsentative Treppe in der Halle und die dienende im Kern sind zwei Haltungen zur gleichen Funktion. Brandschutz drängt Treppen in geschlossene Räume; Entwurfskunst holt sie wieder heraus oder inszeniert das Verschwinden.','Der reale Zielkonflikt: Offene Verbindungstreppen über mehrere Geschosse kollidieren schnell mit der Treppenraum-Logik und sind nur als zusätzliche Treppen oder über Sonderlösungen machbar. Robust ist die Doppelstrategie: der notwendige Treppenraum als ruhige Pflicht, die offene Treppe als Kür innerhalb einer Nutzungseinheit.',NULL,ARRAY['kt3raum']::text[],'[]'::jsonb,NULL,97);